"use strict";
/* Offline playoff and consolation presenter. Read-only views are generated by
   WebManager/Playoff in Pyodide; all writes go through existing real_match.js. */
(() => {
  const $ = id => document.getElementById(id);
  const out = $("output");
  if (!out) return;
  const originalMatchSection = $("matchSelect")?.closest("section");
  originalMatchSection?.classList.add("offline-lab-match-hidden");
  const path = () => location.pathname.replace(/\/$/, "");
  const activeSlug = () => path().split("/").pop();
  const elt = (tag, text, cls) => {
    const node = document.createElement(tag);
    if (text != null) node.textContent = String(text);
    if (cls) node.className = cls;
    return node;
  };
  const pyPresenter = String.raw`
import json, sqlite3, sys, types
from flask import Flask
SOURCE = '/tmp/lab194b.sqlite'
TARGET = '/tmp/st_playoff_view.sqlite'
with sqlite3.connect(SOURCE) as original, sqlite3.connect(TARGET) as isolated:
    original.backup(isolated)
    if isolated.execute('PRAGMA integrity_check').fetchone()[0] != 'ok':
        raise ValueError('Dočasná SQLite kopie je poškozená')
    row = isolated.execute('SELECT source_tournament_id FROM offline_source').fetchone()
    if not row or not isinstance(row[0], int):
        raise ValueError('Chybí ID zdrojového turnaje')
    tournament_id = row[0]
for name in ('app','app.models','app.services','app.services.utils','app.services.tournament','app.web'):
    if name not in sys.modules:
        module = types.ModuleType(name)
        module.__path__ = ['/home/pyodide/' + name.replace('.', '/')]
        sys.modules[name] = module
from app.models.models import db
from app.web.webmanager import WebManager
app = Flask('offline_playoff_presenter')
app.config.update(SQLALCHEMY_DATABASE_URI='sqlite:////tmp/st_playoff_view.sqlite',
                  SQLALCHEMY_TRACK_MODIFICATIONS=False)
db.init_app(app)
with app.app_context():
    try:
        manager = WebManager(tournament_id)
        st_playoff_json = json.dumps({
            'main': manager.get_playoff_page_data(is_consolation=False),
            'consolation': manager.get_playoff_page_data(is_consolation=True)
        }, ensure_ascii=False)
    finally:
        db.session.remove()
        db.engine.dispose()
st_playoff_json
`;

  let lastData = null;
  let playoffData = null;
  let expanded = null; // match ID, stays shared between both views
  let editingMatch = false;
  let version = 0;
  let busy = false;
  let feedback = "";
  let rebuildInProgress = false;

  function syncPageClass() {
    const slug = activeSlug();
    document.body.classList.toggle("offline-live-playoff-page", slug === "playoff");
    document.body.classList.toggle("offline-live-consolation-page", slug === "consolation");
  }
  document.addEventListener("click", event => {
    if (event.target.closest(".offline-nav")) setTimeout(syncPageClass, 0);
  });
  window.addEventListener("popstate", syncPageClass);
  syncPageClass();

  function heading(parent, tag, text, cls) { const n = elt(tag, text, cls); parent.append(n); return n; }

  function matchCard(m) {
    const real = !!m.is_real_match;
    const finished = real && !!m.is_finished;
    const available = real && !finished &&
      m.player_a_name !== "BYE" && m.player_b_name !== "BYE" &&
      Number.isSafeInteger(Number(m.match_id)) && Number(m.match_id) > 0;
    const opened = expanded === m.match_id;
    const card = elt("div", null, "match-card match-center-layout offline-playoff-card" +
      (opened ? " active-match" : ""));
    const aName = real ? m.player_a_name : m.slot_a;
    const bName = real ? m.player_b_name : m.slot_b;
    const aSeed = real ? m.player_a_seed : m.slot_a_seed;
    const bSeed = real ? m.player_b_seed : m.slot_b_seed;
    // Only actual played matches between two players may be corrected.
    const editable = finished && aName !== "BYE" && bName !== "BYE" &&
      Number.isSafeInteger(Number(m.match_id)) && Number(m.match_id) > 0;
    const head = available ? elt("button", null, "offline-playoff-toggle") : elt("div", null, "offline-playoff-static");
    if (available) {
      head.type = "button";
      head.title = "Kliknutím otevřeš zápas";
      head.setAttribute("aria-expanded", String(expanded === m.match_id));
      head.addEventListener("click", () => { if (busy) return; expanded = expanded === m.match_id ? null : m.match_id; draw(); });
    }
    const nameA = elt("strong", aName ?? "Čeká se…", finished && m.winner_name === aName ? "text-winner" : "text-main");
    head.append(nameA);
    if (aSeed) head.append(elt("small", `(${aSeed})`, "text-muted"));
    head.append(elt("div", "vs", "vs-divider"));
    head.append(elt("strong", bName ?? "Čeká se…", finished && m.winner_name === bName ? "text-winner" : "text-main"));
    if (bSeed) head.append(elt("small", `(${bSeed})`, "text-muted"));
    if (available) head.append(elt("span", expanded === m.match_id ? "✕" : "📜", "offline-playoff-indicator"));
    card.append(head);
    if (editable) {
      const finishedLine = elt("div", null, "offline-playoff-finished");
      const gear = elt("button", "⚙️", "offline-playoff-edit-gear");
      gear.type = "button";
      gear.title = "Opravit odehraný zápas";
      gear.setAttribute("aria-label", `Opravit zápas ${aName} – ${bName}`);
      gear.setAttribute("aria-expanded", String(opened && editingMatch));
      gear.style.cssText = "margin-left:.65rem;background:transparent;border:0;color:inherit;cursor:pointer;font-size:1.1em;min-width:32px;min-height:32px";
      gear.addEventListener("click", () => {
        if (busy) return;
        if (opened && editingMatch) { expanded = null; editingMatch = false; }
        else { expanded = m.match_id; editingMatch = true; }
        draw();
      });
      finishedLine.append(gear);
      card.append(finishedLine);
    }
    if (available && opened && !editingMatch) card.append(buildForm(m, false));
    if (editable && opened && editingMatch) card.append(buildForm(m, true));
    return card;
  }

  function buildForm(match, editing = false) {
    const form = elt("form", null, "match-form-column offline-playoff-form");
    if (editing) form.append(elt("p", `Oprava: ${match.player_a_name} – ${match.player_b_name}`, "offline-playoff-edit-label"));
    const originalSets = editing ? (lastData?.match_results || [])
      .filter(row => Number(row.match_id) === Number(match.match_id))
      .sort((a, b) => Number(a.set_number) - Number(b.set_number)) : [];
    const fmt = Number(match.match_format || lastData?.tournaments?.[0]?.playoff_match_format || 3);
    const lines = Math.min(5, Math.max(1, fmt + 1));
    for (let i = 1; i <= lines; i++) {
      const row = elt("label", null, "offline-playoff-set-row");
      row.append(elt("span", `${i}. set:`));
      const a = elt("input"), b = elt("input");
      for (const input of [a, b]) {
        input.type = "number"; input.min = "0"; input.max = "99";
        input.inputMode = "numeric"; input.autocomplete = "off";
      }
      a.dataset.side = "a";
      b.dataset.side = "b";
      if (editing) {
        a.value = originalSets[i - 1]?.score_a ?? "";
        b.value = originalSets[i - 1]?.score_b ?? "";
      }
      row.append(a, elt("span", ":"), b);
      form.append(row);
    }
    const submit = elt("button", editing ? "Uložit opravu" : "Uložit výsledek", "offline-playoff-save");
    submit.type = "submit";
    form.append(submit);
    form.addEventListener("submit", async event => {
      event.preventDefault();
      if (busy) return;
      const values = [...form.querySelectorAll(".offline-playoff-set-row")].map(row => [
        row.querySelector('[data-side="a"]').value.trim(), row.querySelector('[data-side="b"]').value.trim()
      ]);
      let gap = false, count = 0;
      for (const [a,b] of values) {
        if (!a && !b) { gap = true; continue; }
        if (!a || !b || gap || !/^\d+$/.test(a) || !/^\d+$/.test(b) ||
            Number(a) > 99 || Number(b) > 99 || Number(a) === Number(b)) {
          feedback = "❌ Sety musí obsahovat dvě různá skóre 0–99 bez vynechaných řádků.";
          draw(); return;
        }
        count++;
      }
      if (!count) { feedback = "❌ Vyplň alespoň jeden set."; draw(); return; }
      const select = $("matchSelect"), writer = $("submitRealMatch"), mode = $("realMatchMode");
      if (!select || !writer || !mode) {
        feedback = "❌ Chybí formulář offline enginu."; draw(); return;
      }
      // Refresh the hidden writer's available matches for the requested mode.
      mode.value = editing ? "edit" : "new";
      mode.dispatchEvent(new Event("change"));
      if (![...select.options].some(opt => Number(opt.value) === Number(match.match_id))) {
        feedback = "❌ Zápas není dostupný v režimu " + (editing ? "oprav" : "zápisu") + ".";
        draw(); return;
      }
      select.value = String(match.match_id);
      select.dispatchEvent(new Event("change"));
      for (let i = 1; i <= 5; i++) {
        $("setA" + i).value = values[i-1]?.[0] || "";
        $("setB" + i).value = values[i-1]?.[1] || "";
      }
      busy = true;
      submit.disabled = true;
      feedback = editing ? "Opravuji zápas v lokální SQLite…" : "Zapisování výsledku do lokální SQLite…";
      try {
        // Attach both listeners BEFORE clicking; a quick writer can resolve immediately.
        await new Promise((resolve, reject) => {
          let settled = false;
          const status = $("realMatchStatus"), report = $("realMatchReport");
          const onData = () => finish();
          const observer = new MutationObserver(() => {
            if (status?.textContent?.startsWith("❌")) finish(new Error(report?.textContent || status.textContent));
          });
          function finish(error) {
            if (settled) return;
            settled = true;
            window.removeEventListener("offline:tournament-data", onData);
            observer.disconnect();
            error ? reject(error) : resolve();
          }
          window.addEventListener("offline:tournament-data", onData);
          if (status) observer.observe(status, {childList: true, characterData: true, subtree: true});
          writer.click();
        });
        expanded = null;
        editingMatch = false;
        feedback = editing ? "✅ Oprava uložena do zařízení." : "✅ Výsledek uložen do zařízení.";
      } catch (error) {
        feedback = "❌ " + String(error.message || error);
      } finally {
        busy = false;
        draw();
      }
    });
    return form;
  }

  function bracketRounds(target, rounds) {
    const bracket = elt("div", null, "bracket offline-playoff-bracket");
    for (const [name, matches] of Object.entries(rounds || {})) {
      const col = elt("div", null, "round");
      heading(col, "h4", name);
      for (const match of matches) col.append(matchCard(match));
      bracket.append(col);
    }
    if (!bracket.children.length) bracket.append(elt("p", "Pavouk zatím čeká na postupující ze skupin."));
    target.append(bracket);
  }

  function view(name, headingText, data) {
    const section = elt("section", null, "offline-live-playoff offline-live-" + name);
    section.append(elt("h2", headingText, "tournament-section-title"));
    if (feedback) section.append(elt("p", feedback, "offline-playoff-feedback"));
    if (!data) { section.append(elt("p", "Tento pavouk není v turnaji vytvořený.")); return section; }
    if (data.winner) {
      const banner = elt("div", null, "winner-alert");
      banner.append(elt("h3", `Vítěz ${name === "main" ? "turnaje" : "útěchy"}: ${data.winner}`));
      section.append(banner);
    }
    bracketRounds(section, data.rounds);
    if ((data.placement_rounds || []).length) {
      const placement = elt("div", null, "placement-section");
      heading(placement, "h2", "Zápasy o konečné umístění", "placement-header");
      const cols = elt("div", null, "bracket offline-playoff-bracket");
      for (const group of data.placement_rounds) {
        const col = elt("div", null, "round");
        heading(col, "h4", `O ${group.name}. místo`);
        for (const match of group.matches || []) col.append(matchCard(match));
        cols.append(col);
      }
      placement.append(cols);
      section.append(placement);
    }
    return section;
  }

  function draw() {
    // Zapamatovat pozici stránky i všech rodičovských posuvníků.
    const scrollX = window.scrollX;
    const scrollY = window.scrollY;

    const containers = [];
    for (let node = out; node; node = node.parentElement) {
        containers.push({
            element: node,
            left: node.scrollLeft,
            top: node.scrollTop
        });
    }

    // Zapamatovat pozici jednotlivých pavouků.
    const bracketPositions = [
        ...out.querySelectorAll(".offline-playoff-bracket")
    ].map(node => ({
        left: node.scrollLeft,
        top: node.scrollTop
    }));

    out.querySelectorAll(":scope > section.offline-live-playoff")
        .forEach(section => section.remove());

    if (!playoffData || !lastData) return;

    out.append(view("main", "Hlavní playoff", playoffData.main));

    if (playoffData.consolation) {
        out.append(view(
            "consolation",
            "Útěcha – playoff B",
            playoffData.consolation
        ));
    }

    syncPageClass();

    // Vrátit posuvníky na původní pozice.
    const restoreScroll = () => {
        containers.forEach(({ element, left, top }) => {
            element.scrollLeft = left;
            element.scrollTop = top;
        });

        out.querySelectorAll(".offline-playoff-bracket")
            .forEach((node, index) => {
                if (!bracketPositions[index]) return;
                node.scrollLeft = bracketPositions[index].left;
                node.scrollTop = bracketPositions[index].top;
            });

        window.scrollTo(scrollX, scrollY);
    };

    restoreScroll();
    requestAnimationFrame(restoreScroll);
}

  async function rebuild(expected) {
    if (rebuildInProgress) return; // The last finished run will restart for newer data.
    rebuildInProgress = true;
    try {
      do {
        const current = version;
        try {
          const py = await getRuntime();
          await py.loadPackage(["sqlalchemy", "micropip"]);
          try {
              py.runPython("import flask, flask_sqlalchemy");
          } catch (error) {
              await py.runPythonAsync(
                  "import micropip\nawait micropip.install(['flask', 'flask-sqlalchemy'])"
              );
          }
          await ensureEngineFiles(py);
          const raw = await py.runPythonAsync(pyPresenter);
          if (current === version) {
            playoffData = JSON.parse(raw);
            draw();
          }
        } catch (error) {
          if (current === version) {
            console.error("Offline playoff presenter:", error);
            playoffData = null;
            for (const kind of ["main", "consolation"]) {
              const old = out.querySelector(`:scope > section.offline-live-${kind}`);
              old?.remove();
            }
            const broken = elt("section", null, "offline-live-playoff offline-live-main");
            broken.append(elt("h2", "Playoff – chyba zobrazení"));
            broken.append(elt("p", `⚠️ ${String(error.message || error)}`));
            out.append(broken);
          }
        }
        if (current === version) break;
      } while (lastData);
    } finally {
      rebuildInProgress = false;
      // The results presenter runs only AFTER playoff has finished using Pyodide.
      window.dispatchEvent(new CustomEvent("offline:playoff-presented", {
        detail: { version }
      }));
    }
  }

  // The groups presenter owns the first read of the shared Pyodide runtime.
  // It announces completion even on error, so this view does not race it.
  window.addEventListener("offline:tournament-data", event => {
    lastData = event.detail?.data || null;
    expanded = null;
    editingMatch = false;
    version++;
  });
  window.addEventListener("offline:groups-presented", () => {
    if (lastData) rebuild(version);
  });
  window.addEventListener("offline:tournament-removed", () => {
    lastData = null; playoffData = null; version++; expanded = null; editingMatch = false;
    out.querySelectorAll(":scope > section.offline-live-playoff").forEach(s => s.remove());
  });
})();
